svg.script:
const LLM='https://backend.buildpicoapps.com/aero/run/llm-api?pk=v1-Z0FBQUFBQm5HUEtMSjJkakVjcF9IQ0M0VFhRQ0FmSnNDSHNYTlJSblE0UXo1Q3RBcjFPcl9YYy1OZUhteDZWekxHdWRLM1M1alNZTkJMWEhNOWd4S1NPSDBTWC12M0U2UGc9PQ==';
const IMG='https://backend.buildpicoapps.com/aero/run/image-generation-api?pk=v1-Z0FBQUFBQm5HUEtMSjJkakVjcF9IQ0M0VFhRQ0FmSnNDSHNYTlJSblE0UXo1Q3RBcjFPcl9YYy1OZUhteDZWekxHdWRLM1M1alNZTkJMWEhNOWd4S1NPSDBTWC12M0U2UGc9PQ==';
const MODEL='openai/gpt-5.5';
const puterReady=()=>new Promise((res,rej)=>{let n=0;const t=setInterval(()=>{if(window.puter&&window.puter.ai){clearInterval(t);res()}else if(++n>40){clearInterval(t);rej(new Error('Puter did not load'))}},250)});
const ptext=r=>{
  if(!r)return '';
  if(typeof r==='string')return r;
  const c=r.message&&r.message.content;
  if(typeof c==='string')return c;
  if(Array.isArray(c))return c.map(x=>typeof x==='string'?x:(x&&x.text)||'').join('');
  return r.text||(typeof r.toString==='function'&&r.toString()!=='[object Object]'?r.toString():'');
};
const $=id=>document.getElementById(id);
const mk=t=>document.createElementNS('http://www.w3.org/1999/xhtml',t);
const inp=$('chatInput'),btn=$('sendButton'),msgs=$('msgs'),listEl=$('list');
let chats=[],cur=null,busy=false,pic='',docs=[];
try{chats=JSON.parse(localStorage.getItem('chats')||'[]')}catch(e){}
const save=()=>{try{localStorage.setItem('chats',JSON.stringify(chats.slice(0,40),(k,v)=>k==='pic'?undefined:(k==='body'&&typeof v==='string'?v.slice(0,8000):v)))}catch(e){}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>chats.find(x=>x.id===cur);

function fmt(t){
  return t.split('```').map((p,i)=>{
    if(i%2) return '<pre><code>'+esc(p.replace(/^\w*\n/,'').replace(/\n$/,''))+'</code></pre>';
    return esc(p).replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\*\*([^*\n]+)\*\*/g,'<b>$1</b>').replace(/\n/g,'<br/>');
  }).join('');
}
const ICON='<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/></svg>';
function scrollDown(){$('scroll').scrollTo({top:1e9})}

function add(m,anim){
  const r=mk('div');
  r.className='row '+m.r+(anim?' fresh':'');
  if(m.r==='u'){
    r.innerHTML='<div class="b"></div>';
    if(m.pic){const i=new Image();i.src=m.pic;i.alt='Your image';r.firstChild.append(i)}
    (m.docs||[]).forEach(f=>{const c=mk('div');c.className='fchip';c.innerHTML=ICON+'<span></span>';c.lastChild.textContent=f.name;r.firstChild.append(c)});
    r.firstChild.append(document.createTextNode(m.t||''));
  }else{
    r.innerHTML='<div class="av"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" aria-hidden="true"><use href="#ug"/></svg></div><div class="b"></div>';
    try{r.lastChild.innerHTML=fmt(m.t||'')+(m.img?'<img src="'+esc(m.img)+'" alt="Generated image"/>':'')}catch(e){r.lastChild.textContent=m.t||''}
  }
  msgs.append(r);scrollDown();return r;
}
function typing(){
  const r=mk('div');
  r.className='row a fresh';
  r.innerHTML='<div class="av"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" aria-hidden="true"><use href="#ug"/></svg></div><div class="b"><div class="dots"><i></i><i></i><i></i></div></div>';
  msgs.append(r);scrollDown();return r;
}
function renderList(){
  listEl.innerHTML=chats.length?'':'<div class="empty">No chats yet</div>';
  chats.forEach(c=>{
    const d=mk('div');
    d.className='item'+(c.id===cur?' on':'');
    d.dataset.id=c.id;
    d.innerHTML='<span></span><button title="Delete chat" aria-label="Delete chat">×</button>';
    d.firstChild.textContent=c.title;
    listEl.append(d);
  });
}
function render(){
  const c=current();
  $('title').textContent=c?c.title:'New chat';
  $('hello').style.display=c&&c.m.length?'none':'';
  msgs.innerHTML='';
  if(c)c.m.forEach(m=>add(m,false));
  renderList();
}
function newChat(){cur=null;render();inp.focus();if(innerWidth<=760)$('app').classList.add('shut')}
function fit(){inp.style.height='auto';inp.style.height=Math.min(inp.scrollHeight,200)+'px';btn.disabled=busy||!(inp.value.trim()||pic||docs.length)}

function setPic(u){pic=u;$('thumb').hidden=!u;if(u)$('thumbImg').src=u;fit()}
const TEXT_EXT=/\.(txt|md|markdown|html?|css|js|mjs|jsx|ts|tsx|json|csv|tsv|xml|svg|yml|yaml|py|java|c|cpp|h|cs|go|rs|rb|php|sh|sql|ini|toml|log)$/i;
const MAXDOC=40000;
function notice(m){const h=document.querySelector('.hint');if(!h.dataset.o)h.dataset.o=h.textContent;h.textContent=m;clearTimeout(h._t);h._t=setTimeout(()=>{h.textContent=h.dataset.o},5000)}
function renderDocs(){
  const d=$('docs');d.hidden=!docs.length;d.innerHTML='';
  docs.forEach((f,i)=>{
    const c=mk('div');c.className='fchip';
    c.innerHTML=ICON+'<span></span><button aria-label="Remove file">\u00d7</button>';
    c.querySelector('span').textContent=f.name;
    c.querySelector('button').addEventListener('click',()=>{docs.splice(i,1);renderDocs();fit();inp.focus()});
    d.append(c);
  });
}
function rasterize(f){
  const rd=new FileReader();
  rd.onload=()=>{
    const im=new Image();
    im.onload=()=>{
      const W=im.naturalWidth||512,H=im.naturalHeight||512;
      const k=Math.min(1,1024/Math.max(W,H)),c=mk('canvas'),x=c.getContext('2d');
      c.width=Math.round(W*k);c.height=Math.round(H*k);
      x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);
      try{setPic(c.toDataURL('image/jpeg',.85))}catch(e){}
      inp.focus();
    };
    im.src=rd.result;
  };
  rd.readAsDataURL(f);
}
function loadFile(f){
  if(!f)return;
  const svg=f.type==='image/svg+xml'||/\.svg$/i.test(f.name);
  if(f.type.startsWith('image/')&&!svg){rasterize(f);return}
  if(svg||f.type.startsWith('text/')||/json|xml|javascript/.test(f.type)||TEXT_EXT.test(f.name)){
    if(f.size>2e6){notice('That file is too big (2 MB max).');return}
    const rd=new FileReader();
    rd.onload=()=>{
      const t=String(rd.result);
      if(t.includes('\u0000')){notice("I can't read that file. Try an image, HTML, SVG, or a text/code file.");return}
      docs.push({name:f.name,body:t.slice(0,MAXDOC),cut:t.length>MAXDOC});
      renderDocs();fit();inp.focus();
      if(svg&&!pic)rasterize(f);
    };
    rd.readAsText(f);
    return;
  }
  notice("I can't read that file type yet. Try an image, HTML, SVG, or a text/code file.");
}
function imgProgress(){
  const r=mk('div');
  r.className='row a fresh';
  r.innerHTML='<div class="av"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" aria-hidden="true"><use href="#ug"/></svg></div><div class="b"><div class="gen"><div class="ph"></div><div class="lab"><span></span><span></span></div><div class="bar"><i></i></div></div></div>';
  msgs.append(r);scrollDown();
  const sp=r.querySelectorAll('.lab span'),bar=r.querySelector('.bar i');
  const stages=[[0,'Understanding your idea\u2026'],[12,'Making first draft\u2026'],[40,'Adding details\u2026'],[70,'Adding final touches\u2026']];
  let p=0;
  const set=v=>{p=v;bar.style.width=v+'%';sp[1].textContent=Math.round(v)+'%';sp[0].textContent=stages.filter(s=>v>=s[0]).pop()[1]};
  set(2);
  r.stop=()=>clearInterval(r._t);
  r._t=setInterval(()=>set(p+Math.max(.15,(94-p)*.035)),350);
  r.finish=()=>new Promise(res=>{r.stop();set(100);sp[0].textContent='Done!';setTimeout(res,450)});
  return r;
}

async function send(text){
  text=(text===undefined?inp.value:text).trim();
  const p=pic,ds=docs.slice();
  if((!text&&!p&&!ds.length)||busy)return;
  let c=current();
  if(!c){c={id:Date.now(),title:(text||(ds[0]&&ds[0].name)||'Image').slice(0,40),m:[]};chats.unshift(c);cur=c.id;$('title').textContent=c.title}
  busy=true;inp.value='';setPic('');docs=[];renderDocs();
  $('hello').style.display='none';
  const hist=c.m.slice(-12);
  const um={r:'u',t:text,pic:p,docs:ds};
  c.m.push(um);
  add(um,true);renderList();save();
  const wait=text.startsWith('/image')?imgProgress():typing();
  const isImg=text.startsWith('/image');
  const q=text||(p&&!ds.length?'Describe this image.':'Look at what I attached and tell me what it is and what it contains.');
  const SYS='You are UltraGPT, a helpful AI assistant. The user can attach images and files. You CAN see attached images, and the full text of attached files (HTML, SVG, code, text and so on) is included in the message. Never say that you cannot see or open an attachment; look at it and answer.';
  const fb=(x,lim)=>(x.docs||[]).map(f=>'[Attached file: '+f.name+(f.cut?' (cut short)':'')+']\n'+f.body.slice(0,lim)+'\n[End of file]').join('\n\n');
  const lastPic=(hist.slice().reverse().find(x=>x.pic)||{}).pic||'';
  const sendPic=p||lastPic;
  let prompt;
  if(isImg){prompt=text.replace(/^\/image\s*/,'')||text}
  else{
    const cur=(ds.length?fb({docs:ds},MAXDOC)+'\n\n':'')+q;
    const hx=hist.filter(x=>!(x.r==='a'&&!x.t&&x.img)&&!String(x.t).startsWith('Something went wrong')).map(x=>(x.r==='u'?'User: ':'Assistant: ')+[fb(x,6000),x.t||(x.pic?'[image]':'')].filter(Boolean).join('\n')).join('\n');
    prompt=SYS+'\n\n'+(hx?'Conversation so far:\n'+hx+'\n\n':'')+'User: '+cur+'\nAssistant:';
  }
  const legacy=async b=>{
    const r=await fetch(isImg?IMG:LLM,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});
    const j=await r.json();
    if(!j||j.status!=='success')throw new Error('API said: '+JSON.stringify(j).slice(0,200));
    return j;
  };
  const post=async b=>{
    try{
      await puterReady();
      if(isImg){
        const im=await puter.ai.txt2img(b.prompt);
        const src=im&&(im.src||im.url||(typeof im==='string'?im:''));
        if(!src)throw new Error('Puter returned no image');
        return {status:'success',imageUrl:String(src)};
      }
      const opts={model:MODEL};
      const r=(b.images&&b.images.length)?await puter.ai.chat(b.prompt,b.images[0],opts):await puter.ai.chat(b.prompt,opts);
      const t=ptext(r);
      if(!t)throw new Error('Puter returned an empty reply');
      return {status:'success',text:t};
    }catch(e){
      console.warn('Puter failed, trying the backup service:',e);
      return await legacy(b);
    }
  };
  const tries=async list=>{
    let last;
    for(const b of list){try{return await post(b)}catch(e){last=e;console.warn('Attempt failed:',e)}}
    throw last;
  };
  try{
    let note='',d;
    if(isImg){
      d=await tries([{prompt},{prompt}]);
    }else{
      // compact fallback prompt: recent plain text only, no generated-image turns
      const plain=hist.slice(-6).filter(x=>!x.img).map(x=>(x.r==='u'?'User: ':'Assistant: ')+(x.t||'').slice(0,1500)).filter(l=>l.length>12).join('\n');
      const small=SYS+'\n\n'+(plain?'Conversation so far:\n'+plain+'\n\n':'')+'User: '+(ds.length?fb({docs:ds},MAXDOC)+'\n\n':'')+q+'\nAssistant:';
      const list=[];
      if(sendPic)list.push({prompt,images:[sendPic]});
      list.push({prompt},{prompt:small});
      try{d=await tries(list)}
      catch(e){d=await tries([{prompt:q}])}
    }
    if(wait.finish)await wait.finish();
    wait.remove();
    const m={r:'a',t:note+(d.text||''),img:d.imageUrl||d.image||''};
    if(!m.t&&!m.img)m.t='(No response came back.)';
    c.m.push(m);add(m,true);
  }catch(e){
    console.error('Error:',e);
    if(wait.stop)wait.stop();
    wait.remove();
    const m={r:'a',t:'Something went wrong. Please try again.\n\n(Details: '+String(e&&e.message||e).slice(0,160)+')'};
    c.m.push(m);add(m,true);
  }
  busy=false;save();fit();inp.focus();
}

inp.addEventListener('input',fit);
inp.addEventListener('keydown',e=>{
  if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send()}
});
btn.addEventListener('click',()=>send());
$('clip').addEventListener('click',()=>$('file').click());
$('file').addEventListener('change',e=>{[...e.target.files].forEach(loadFile);e.target.value=''});
$('thumbX').addEventListener('click',()=>{setPic('');inp.focus()});
inp.addEventListener('paste',e=>{
  const fs=[...e.clipboardData.files];
  if(fs.length){e.preventDefault();fs.forEach(loadFile)}
});
addEventListener('dragover',e=>e.preventDefault());
addEventListener('drop',e=>{e.preventDefault();[...e.dataTransfer.files].forEach(loadFile)});
$('newChat').addEventListener('click',newChat);
$('menu').addEventListener('click',()=>$('app').classList.toggle('shut'));
document.querySelector('.chips').addEventListener('click',e=>{
  if(e.target.classList.contains('chip'))send(e.target.textContent);
});
listEl.addEventListener('click',e=>{
  const it=e.target.closest('.item');if(!it)return;
  const id=+it.dataset.id;
  if(e.target.tagName==='BUTTON'){
    chats=chats.filter(x=>x.id!==id);save();
    if(cur===id)cur=null;
    render();
  }else if(!busy){
    cur=id;render();
    if(innerWidth<=760)$('app').classList.add('shut');
  }
});

const h=new Date().getHours();
$('greet').textContent=(h<12?'Good morning':h<18?'Good afternoon':'Good evening')+', how can I help?';
if(innerWidth<=760)$('app').classList.add('shut');
render();inp.focus();
